/* @autogenerated */
package net.civeira.phylax.feature.oauth.delegatelogin.application;

import java.util.List;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.mockito.ArgumentMatchers;
import org.mockito.Mockito;

import net.civeira.phylax.feature.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.feature.oauth.delegatelogin.application.DelegateLogin.Started;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.DelegatedAccessExternalProvider;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.DelegatedAccessExternalProvider.RequestInfo;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.DelegatedRequestDetails;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.FederatedUser;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.PendingDelegation;
import net.civeira.phylax.feature.oauth.delegatelogin.domain.gateway.DelegateLoginGateway;

class DelegateLoginUnitTest {
  private static final String TENANT = "acme";
  private static final String PROVIDER = "corp";
  private static final String CLIENT = "web";

  private DelegateLoginGateway gateway = Mockito.mock(DelegateLoginGateway.class);
  private DelegatedAccessExternalProvider external =
      Mockito.mock(DelegatedAccessExternalProvider.class);
  private AuthRequest request = AuthRequest.builder().tenant(TENANT).build();
  private DelegateLogin login;
  private FederatedUser user =
      FederatedUser.builder().subject("sub-1").email("a@b.com").emailVerified(true).build();

  @BeforeEach
  void setUp() {
    Mockito.reset(gateway, external);
    Mockito.when(external.getId(ArgumentMatchers.any())).thenReturn(PROVIDER);
    Mockito.when(external.request(ArgumentMatchers.any(), ArgumentMatchers.any()))
        .thenReturn(new RequestInfo());
    Mockito.when(gateway.providers(ArgumentMatchers.any())).thenReturn(List.of(external));
    login = new DelegateLogin(gateway);
  }

  /**
   * Starts a login and returns the pending login stored, its state and binding.
   */
  private Object[] started() {
    Started started = login.start(request, PROVIDER, CLIENT, "https://cb", "/ret").orElseThrow();
    ArgumentCaptor<PendingDelegation> pending = ArgumentCaptor.forClass(PendingDelegation.class);
    ArgumentCaptor<String> hash = ArgumentCaptor.forClass(String.class);
    Mockito.verify(gateway).savePending(hash.capture(), pending.capture());
    ArgumentCaptor<DelegatedRequestDetails> details =
        ArgumentCaptor.forClass(DelegatedRequestDetails.class);
    Mockito.verify(external).request(ArgumentMatchers.any(), details.capture());
    String state = details.getValue().getState();
    Assertions.assertEquals(PendingDelegation.hash(state), hash.getValue());
    return new Object[] {pending.getValue(), state, started.getBinding()};
  }

  @Test
  @DisplayName("start binds the pending login to the request, client and browser")
  void test_start() {
    Object[] started = started();
    PendingDelegation pending = (PendingDelegation) started[0];
    Assertions.assertEquals(TENANT, pending.getTenant());
    Assertions.assertEquals(CLIENT, pending.getClientId());
    Assertions.assertEquals(PendingDelegation.requestIdFor((String) started[1]),
        pending.getRequestId());
    Assertions.assertTrue(pending.boundTo((String) started[2]));
    Assertions.assertNotEquals(started[1], started[2], "State and binding must differ");
  }

  @Test
  @DisplayName("start with an unknown provider stores nothing")
  void test_start_unknown_provider() {
    Assertions.assertTrue(login.start(request, "other", CLIENT, "https://cb", "/ret").isEmpty());
    Mockito.verify(gateway, Mockito.never()).savePending(ArgumentMatchers.any(),
        ArgumentMatchers.any());
  }

  @Test
  @DisplayName("complete resolves the account of a valid response")
  void test_complete() {
    Object[] started = started();
    String state = (String) started[1];
    Mockito.when(gateway.consumePending(TENANT, PendingDelegation.hash(state)))
        .thenReturn(Optional.of((PendingDelegation) started[0]));
    Mockito.when(external.authenticate(ArgumentMatchers.any(), ArgumentMatchers.any(),
        ArgumentMatchers.any())).thenReturn(Optional.of(user));
    Mockito.when(gateway.resolveAccount(request, PROVIDER, user)).thenReturn(Optional.of("alice"));

    Assertions.assertEquals(Optional.of("alice"),
        login.complete(request, CLIENT, PROVIDER, state, (String) started[2], Map.of()));
  }

  @Test
  @DisplayName("complete refuses a used or unknown state without calling the provider")
  void test_complete_consumed() {
    Mockito.when(gateway.consumePending(ArgumentMatchers.any(), ArgumentMatchers.any()))
        .thenReturn(Optional.empty());
    Assertions.assertTrue(login.complete(request, CLIENT, PROVIDER, "s", "b", Map.of()).isEmpty());
    Mockito.verify(external, Mockito.never()).authenticate(ArgumentMatchers.any(),
        ArgumentMatchers.any(), ArgumentMatchers.any());
  }

  @Test
  @DisplayName("complete refuses another browser, client or provider")
  void test_complete_mismatch() {
    Object[] started = started();
    String state = (String) started[1];
    String binding = (String) started[2];
    Mockito.when(gateway.consumePending(TENANT, PendingDelegation.hash(state)))
        .thenReturn(Optional.of((PendingDelegation) started[0]));

    Assertions
        .assertTrue(login.complete(request, CLIENT, PROVIDER, state, "other", Map.of()).isEmpty());
    Assertions
        .assertTrue(login.complete(request, CLIENT, PROVIDER, state, null, Map.of()).isEmpty());
    Assertions.assertTrue(
        login.complete(request, "other-client", PROVIDER, state, binding, Map.of()).isEmpty());
    Assertions
        .assertTrue(login.complete(request, CLIENT, "other", state, binding, Map.of()).isEmpty());
    Mockito.verify(external, Mockito.never()).authenticate(ArgumentMatchers.any(),
        ArgumentMatchers.any(), ArgumentMatchers.any());
  }

  @Test
  @DisplayName("complete refuses a response the provider rejects")
  void test_complete_rejected_by_provider() {
    Object[] started = started();
    String state = (String) started[1];
    Mockito.when(gateway.consumePending(TENANT, PendingDelegation.hash(state)))
        .thenReturn(Optional.of((PendingDelegation) started[0]));
    Mockito.when(external.authenticate(ArgumentMatchers.any(), ArgumentMatchers.any(),
        ArgumentMatchers.any())).thenReturn(Optional.empty());

    Assertions.assertTrue(
        login.complete(request, CLIENT, PROVIDER, state, (String) started[2], Map.of()).isEmpty());
    Mockito.verify(gateway, Mockito.never()).resolveAccount(ArgumentMatchers.any(),
        ArgumentMatchers.any(), ArgumentMatchers.any());
  }
}
